# ---- hide the full word-list grids (learner Words page, parent Progress) ----
R('<section class="card panel"><h2>All my words</h2><div class="words">${ws.map((w,j)=>`<div class="word ${j===i?"cur":""}"><div><b>${esc(w.w)}</b><span>${esc(w.m)}</span></div>${sp?`<button class="iconbtn" data-act="say" data-w="${esc(w.w)}" data-l="${esc(w.lang)}" aria-label="Hear ${esc(w.w)}">${ic("sound")}</button>`:""}</div>`).join("")}</div></section>', "")
R('<section class="card panel"><div class="ph"><h2>Words learned <span class="pill p-mute num">${ws.length}</span></h2>${speak&&ws.length?`<span class="small muted">Tap 🔊 to hear a word</span>`:""}</div>\n    ${ws.length?`<div class="words">${ws.map(x=>`<div class="word"><div><b>${esc(x.w)}</b><span>${esc(x.m)}</span></div>${speak?`<button class="iconbtn" data-act="say" data-w="${esc(x.w)}" data-l="${esc(x.lang)}" aria-label="Hear ${esc(x.w)}">${ic("sound")}</button>`:""}</div>`).join("")}</div>`:`<p class="muted">Words from finished lessons collect here.</p>`}</section>', "")
